grid2=[[0]*26 for _ in range(26)]
# redraw via helpers that default overwrite marker when pixels added, currently funcs refer g argument okay
# reuse definitions by redraw
for color,o,pts in [(7,(4,7),p7),(8,(6,7),p8),(5,(11,7),p5),(4,(16,6),p4),(3,(21,12),p3),(1,(18,12),pB),(1,(18,16),pA)]: drawp(grid2,color,o,pts)
for o,pts in [((4,7),d7),((6,7),d8),((11,7),d5),((16,6),d4),((21,12),d3),((18,12),dB),((18,16),dA)]: drawd(grid2,o,pts)
print('\n'.join(' '.join(map(str,row)) for row in grid2))

grid3=[[0]*26 for _ in range(26)]
# draw helper uses collision checks
parts=[(7,(1,10),p7),(8,(3,10),p8),(5,(8,10),p5),(4,(13,9),p4),(3,(18,15),p3),(1,(15,15),pB),(1,(15,19),pA)]
for color,o,pts in parts: drawp(grid3,color,o,pts)
for o,pts in [((1,10),d7),((3,10),d8),((8,10),d5),((13,9),d4),((18,15),d3),((15,15),dB),((15,19),dA)]: drawd(grid3,o,pts)
print('\n'.join(' '.join(map(str,row)) for row in grid3))

# encode pixel and marker offsets relative roots used
T_objs=[((0,0),p7),((2,0),p8),((7,0),p5)]
C_objs=[((0,0),p4),((5,6),p3),((2,6),pB),((2,10),pA)]
T_pix={(dr+rr,dc+cc) for (rr,cc),ps in T_objs for dr,dc in ps}
C_pix={(dr+rr,dc+cc) for (rr,cc),ps in C_objs for dr,dc in ps}
T_dots={(7+dr,dc) for dr,dc in d5 if (dr,dc) in [ (2,-1),(4,2)]}
# markers around C not connected to internal motifs
C_dots={(dr,dc) for dr,dc in d4 if (dr,dc) in [(-1,3),(3,-1),(0,5)]}
# A top/right dots relative to C root (4 bbox)
C_dots |= {(2+0,10+1),(2+1,10+6)}
# candidate single-point alignments
cands=[]
for tp in T_dots:
 for cp in C_dots:
  delta=(tp[0]-cp[0],tp[1]-cp[1]) # C_root such that cp+delta = tp
  pixov=T_pix & {(r+delta[0],c+delta[1]) for r,c in C_pix}
  if not pixov:
   combined=[(r,c) for r,c in T_pix]+[(r+delta[0],c+delta[1]) for r,c in C_pix]
   minr=min(r for r,c in combined);maxr=max(r for r,c in combined);minc=min(c for r,c in combined);maxc=max(c for r,c in combined)
   cands.append((delta,tp,cp,(minr,maxr,minc,maxc)))
print('T dots',T_dots,'C dots',C_dots)
print('valid candidates',len(cands))
for x in cands: print(x)
